CREATE VIEW order_fact AS WITH i AS (SELECT order_id,COUNT(*) items,SUM(price) revenue,SUM(freight_value) freight FROM order_items GROUP BY order_id), r AS (SELECT order_id,AVG(review_score) review_score FROM order_reviews GROUP BY order_id) SELECT o.*,c.customer_state state,substr(order_purchase_timestamp,1,7) month,coalesce(items,0) items,coalesce(revenue,0) revenue,coalesce(freight,0) freight,review_score,CASE WHEN order_delivered_customer_date IS NOT NULL AND order_estimated_delivery_date IS NOT NULL THEN 1 ELSE 0 END eligible,CASE WHEN order_delivered_customer_date IS NOT NULL AND order_estimated_delivery_date IS NOT NULL THEN date(order_delivered_customer_date)>date(order_estimated_delivery_date) END late,julianday(order_delivered_customer_date)-julianday(order_purchase_timestamp) delivery_days FROM orders o LEFT JOIN customers c USING(customer_id) LEFT JOIN i USING(order_id) LEFT JOIN r USING(order_id);
CREATE VIEW item_fact AS SELECT i.*,f.state,f.month,f.late,f.delivery_days,s.seller_state,coalesce(t.product_category_name_english,'unknown') category FROM order_items i JOIN order_fact f USING(order_id) LEFT JOIN sellers s USING(seller_id) LEFT JOIN products p USING(product_id) LEFT JOIN product_category_name_translation t USING(product_category_name);
